//! Per-BUILD bindings for the fragment kernel; only authored templates create
//! records. A missing old-pack template leaves its existing artwork adapter.
use crate::{Game,Value,original_building_fragments as native,original_display::Record};
pub(super) struct State{pools:Vec<native::Pool>,bindings:[Option<usize>;35],templates:Vec<Option<Vec<[i16;6]>>>,draws:Vec<(Record,usize,usize)>}
impl Default for State{fn default()->Self{Self{pools:vec![native::Pool::default();35],bindings:[None;35],templates:vec![None;35],draws:vec![]}}}
impl State{
 pub(super) fn import(previous:Option<&Self>,v:&Value)->Self{let mut next=Self::default();if let Some(old)=previous{next.pools=old.pools.clone();}for p in &mut next.pools{p.clear();}
  for entry in v["nativeBuildingFragments"].as_array().into_iter().flatten(){let Some(slot)=entry["nativeSlot"].as_u64().and_then(|s|usize::try_from(s).ok()).filter(|s|*s<35)else{continue;};let Some(rows)=entry["templates"].as_array().filter(|r|r.len()<=50)else{continue;};let parsed=rows.iter().map(|r|{let a=r.as_array().filter(|r|r.len()==6)?;let mut t=[0;6];for(i,v)in a.iter().enumerate(){t[i]=i16::try_from(v.as_i64()?).ok()?;}Some(t)}).collect::<Option<Vec<_>>>();next.templates[slot]=parsed;
  }next
 }
}
impl Game{
 pub(crate) fn initialize_native_building_fragments(&mut self,slot:usize){let Some(world)=&mut self.native_world else{return;};let Some(b)=world.buildings.get(slot)else{return;};if slot>=35||b.record.kind==-1{return;}let ordinal=world.buildings[..slot].iter().filter(|b|b.record.kind!=-1).count();if ordinal>=35{return;}world.fragments.bindings[slot]=Some(ordinal);if let Some(t)=world.fragments.templates[slot].as_ref(){world.fragments.pools[ordinal].construct(b.record.position,t,b.maximum/5);}}
 pub(crate) fn clear_native_building_fragment_draws(&mut self){if let Some(world)=&mut self.native_world{world.fragments.draws.clear();}}
 pub(crate) fn native_building_fragment_draws(&self)->Vec<(Record,usize,usize)>{self.native_world.as_ref().map_or_else(Vec::new,|w|w.fragments.draws.clone())}
 pub(crate) fn advance_native_building_fragments(&mut self,slot:usize,damage:i16){let Some(world)=&mut self.native_world else{return;};let Some(ordinal)=world.fragments.bindings.get(slot).copied().flatten()else{return;};if world.fragments.templates[slot].is_none(){return;}let mut pool=std::mem::take(&mut world.fragments.pools[ordinal]);let(camera,size)=self.native_view.unwrap_or(([0,0],[(self.map.width*16)as i16,(self.map.height*16)as i16]));let view=native::View{camera,size,multiplayer:self.multiplayer};let mut env=Env{game:self,camera,slot,submitted:0,contact_mode:false};pool.advance(damage,view,&mut env);if let Some(world)=&mut env.game.native_world{world.fragments.pools[ordinal]=pool;}}
}
struct Env<'a>{game:&'a mut Game,camera:[i16;2],slot:usize,submitted:usize,contact_mode:bool}
impl native::World for Env<'_>{
 fn contact_mode(&mut self,enabled:bool){self.contact_mode=enabled;}
 fn submit(&mut self,mut r:Record){r.x=r.x.wrapping_add(self.camera[0]);r.y=r.y.wrapping_add(self.camera[1]);if let Some(world)=&mut self.game.native_world{world.fragments.draws.push((r,self.slot*50+self.submitted,self.slot));}self.submitted+=1;}
 //The existing source environment adapter owns zero-strength OBJECT/terrain
 //contacts. Its general auxiliary audio/global boundaries remain explicit.
 fn environment(&mut self,p:[i16;2]){debug_assert!(self.contact_mode);self.game.native_blast_environment(i32::from(p[0]),i32::from(p[1]),0,255,false);}
 fn spark(&mut self,p:[i16;2]){let random=if self.game.multiplayer{0}else{self.game.native_cosmetic_random()};self.game.native_ambient_animations.spawn_spark(p,random);}
 fn crt(&mut self)->u16{self.game.native_cosmetic_random()}
}
#[cfg(test)]mod tests{
 use super::*;use crate::json;
 fn field()->Game{let mut g=Game::new(0,1,41610);let mut b=g.buildings[0].clone();let mut sector=g.sectors[0].clone();g.map.original=true;g.map.width=64;g.map.height=64;g.map.tiles=vec![0;4096];g.map.terrain_codes=vec![0;4096];g.map.native_terrain_plane=vec![0;16384];g.map.original_tiles=vec![0;4096];g.map.territory=vec![0;4096];g.map.bridge_base=vec![-1;4096];g.units.clear();g.buildings.clear();g.objects.clear();g.crates.clear();g.walls.clear();g.native_world=None;g.native_strategy=None;g.native_group_rosters=Default::default();g.native_display=Default::default();b.id=77;b.kind="repair".into();b.x=800.;b.y=1000.;b.w=160.;b.h=128.;b.team=0;b.sector=0;b.hp=100.;b.max_hp=100.;b.raw_base=None;b.product=None;sector.id=0;sector.owner=0;g.sectors=vec![sector];g.buildings=vec![b];g.import_native_world(&json!({"nativeWorldBuildings":[{"nativeSlot":3,"kind":0,"x":400,"y":500,"hp":100,"maxHp":100,"buildingId":77}],"nativeBuildingFragments":[{"nativeSlot":3,"templates":[[10,20,-1782,1,4,2],[20,30,407,1,9,1]]}]}));let fields=crate::original_factory::constructor_fields(0,0,100,false,||0,||0).unwrap();g.set_native_building_constructor(3,fields);g.native_team_rates[0]=26;g.ai_teams.clear();g}
 #[test]fn live_workshop_fragments_keep_their_original_queue_offset_and_captured_picture(){let mut g=field();let world=g.native_world.as_ref().unwrap();assert_eq!(world.fragments.bindings[3],Some(0));assert_eq!(world.fragments.pools[0].records[0].word(0),410);assert_eq!(world.fragments.pools[0].records[0].word(2),488);assert_eq!(world.fragments.pools[0].records[1].bytes[13],4,"41f8f0 uses the table's first timing row");g.buildings[0].hp=80.;g.sync_native_world();g.advance_native_workshop_slot(3);assert!(g.native_building_fragment_draws().is_empty(),"activation does not draw in that same41f610 iteration");g.native_cosmetic_rng=1;g.begin_native_display_frame();g.advance_native_workshop_slot(3);let rows=g.native_display_queue().into_iter().filter(|r|r["source"]=="buildingFragment").collect::<Vec<_>>();assert_eq!(rows.len(),2);assert_eq!((rows[0]["x"].as_i64(),rows[0]["y"].as_i64(),rows[0]["queueY"].as_i64()),(Some(820),Some(976),Some(776)));assert_eq!(rows[0]["sprite"],1782);assert_eq!(g.native_cosmetic_rng,1u32.wrapping_mul(214013).wrapping_add(2531011));g.buildings[0].hp=0.;g.sync_native_world();assert_eq!(g.native_display_queue().into_iter().filter(|r|r["source"]=="buildingFragment").collect::<Vec<_>>(),rows);g.begin_native_display_frame();assert!(g.native_building_fragment_draws().is_empty());}
 #[test]fn fragment_mission_reset_retires_only_x_and_rebinds_the_compact_active_pool(){let mut g=field();let world=g.native_world.as_mut().unwrap();world.fragments.pools[0].records[0].bytes[4]=203;world.fragments.pools[0].records[0].bytes[17]=119;let v=json!({"nativeBuildingFragments":[{"nativeSlot":15,"templates":[[7,9,-1782,1,4,2]]}]});let mut reset=State::import(Some(&world.fragments),&v);assert_eq!(reset.pools[0].records[0].word(0),-1);reset.pools[0].construct([500,600],reset.templates[15].as_ref().unwrap(),300);let r=reset.pools[0].records[0];assert_eq!((r.word(0),r.word(2),r.bytes[4],r.bytes[17]),(507,577,203,119));assert!(reset.bindings.iter().all(Option::is_none));}
 #[test]fn optional_authored_repair_fragment_templates_bind_all_twenty_one_workshops(){let path=std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("../dist/original/campaign.json");let Ok(bytes)=std::fs::read(path)else{return;};let campaign:Value=serde_json::from_slice(&bytes).unwrap();if campaign["missions"][0].get("nativeBuildingFragments").is_none(){return;}let mut count=0;for m in campaign["missions"].as_array().unwrap(){let mut g=Game::new(0,1,41610);g.apply_original(m).unwrap();let world=g.native_world.as_ref().unwrap();for entry in m["nativeBuildingFragments"].as_array().unwrap(){let slot=entry["nativeSlot"].as_u64().unwrap()as usize;let ordinal=world.fragments.bindings[slot].unwrap();assert_eq!(world.fragments.templates[slot].as_ref().unwrap().len(),25);assert_eq!(world.fragments.pools[ordinal].records.iter().filter(|r|r.word(0)!=-1).count(),25);let b=&world.buildings[slot];assert_eq!(world.fragments.pools[ordinal].records[0].word(0),b.record.position[0]+17);count+=1;}}assert_eq!(count,21);}
}
